// =============== DETECTION (Q223-231) ===============
{
  const A = makeAuthor("detect", "Book 2"); const io = ["detect-iou"], nm = ["detect-nms"];
  A.blanks("b2-q223", "Medium", "A (0, 0)–(6, 4), B (2, 0)–(8, 4). Area A ___; overlap ___; union ___; IoU ___. If A scores higher and suppression requires IoU strictly greater than 0.40, is B suppressed (yes/no)? ___", ["area A", "overlap", "union", "IoU", "suppressed?"], ["24", "16", "32", "0.50", "yes"], [["24"], ["16"], ["32"], ["0.50", "0.5", "1/2"], ["yes", "y"]], "Overlap 4 × 4.", C(223, [...io, ...nm], { steps: ["overlap width min(6,8) − max(0,2) = 4; height 4", "union 24 + 24 − 16 = 32", "IoU 0.50 > 0.40 → suppress B"] }));
  const iou = (n, stem, ans, steps) => A.blank(`b2-q${n}`, "Medium", stem, ans, [], "IoU = I/(A + B − I).", C(n, io, { steps }));
  iou(224, "A (1, 1)–(5, 5), B (3, 2)–(7, 6). IoU = ___ (3 d.p.).", "0.231", ["overlap (5 − 3) × (5 − 2) = 6", "union 16 + 16 − 6 = 26", "6/26 = 0.231"]);
  iou(225, "A (0, 0)–(4, 4), B (2, 2)–(6, 6). IoU = ___ (3 d.p.).", "0.143", ["overlap 2 × 2 = 4", "union 28", "4/28 = 0.143"]);
  iou(226, "A (0, 0)–(10, 10), B (5, 0)–(15, 10). IoU = ___ (3 d.p.).", "0.333", ["overlap 50", "union 150", "0.333"]);
  A.tf("b2-q227", "Medium", "Two boxes have IoU exactly 0.50 and the rule is 'suppress if IoU > 0.5'. The lower-scored box is suppressed.", false, "Equality does not trigger 'strictly greater'.", "Read > vs ≥.", P(227, nm));
  A.multi("b2-q228", "Hard", "NMS, rule 'IoU > 0.5 suppresses'. Boxes: A car 0.90 (0,0)–(4,4); B car 0.80 (1,1)–(5,5); C car 0.75 (0,0)–(4,3); D person 0.70 (1,0)–(5,4). Which boxes remain?", [["A", true, "highest score, kept"], ["B", true, "IoU(A,B) = 9/23 = 0.39 ≤ 0.5"], ["C", false, "IoU(A,C) = 12/16 = 0.75 → suppressed"], ["D", true, "different class, never compared with cars"]], "NMS is per class.", C(228, nm, { steps: ["Keep A.", "IoU(A,B) = 9/(16 + 16 − 9) = 0.39 → keep B.", "IoU(A,C) = 12/16 = 0.75 → suppress C.", "D is a person: separate class."] }));
  A.mcq("b2-q229", "Easy", "YOLO's key idea is to:", "run the CNN once and predict boxes everywhere on a shared feature map", [["classify 57,600 crops separately", "That is the naive approach."], ["use only fully connected layers", "It is convolutional."], ["segment each pixel", "That is segmentation."]], "You Only Look Once.", P(229, "detect-yolo"));
  A.blank("b2-q230", "Medium", "A YOLO head on a 20 × 20 feature map with C classes outputs a tensor of shape 20 × 20 × (___ + C).", "5", [], "Box 4 + objectness 1 + C class scores.", C(230, "detect-yolo"));
  A.match("b2-q231", "Easy", "Match the vision task to its output.", [["classification", "one label for the whole image"], ["object detection", "boxes, labels and confidences for every object"], ["semantic segmentation", "a class label for every pixel"]], [], "What vs what + where vs per pixel.", P(231, ["detect-task", "detect-seg"]));
  out.detect = A.out;
}

