  A.mcq("b2-q315", "Medium", "With precedence ¬, ∧, ∨, ⇒, ⇔, ¬P ∨ Q ∧ R ⇒ S is read as:", "((¬P) ∨ (Q ∧ R)) ⇒ S", [["¬(P ∨ Q) ∧ (R ⇒ S)", "¬ binds only P."], ["(¬P ∨ Q) ∧ (R ⇒ S)", "∧ binds tighter than ∨ and ⇒ is last."], ["¬P ∨ (Q ∧ (R ⇒ S))", "⇒ is weakest, so it is applied last."]], "Not, and, or, implies, iff.", P(315, sy));
  A.tf("b2-q316", "Easy", "'If 2 + 2 = 5, then x > 3' is true.", true, "A false premise makes the implication vacuously true.", "F ⇒ anything = T.", P(316, se));
  A.tf("b2-q317", "Easy", "'If x > 5 then x < 3' is true for all x.", false, "x = 6 makes the premise true and conclusion false.", "Only T ⇒ F is false.", P(317, se));
  A.tf("b2-q318", "Easy", "P ⇒ Q means P causes Q.", false, "Implication asserts no causation.", "Truth, not cause.", P(318, se));
  A.blanks("b2-q319", "Medium", "P = T, Q = F, R = T. Evaluate (T/F): P ∧ Q; P ∨ Q; P ⇒ Q; Q ⇒ R; P ⇔ R; ¬P ∨ Q ∧ R ⇒ Q.", ["P ∧ Q", "P ∨ Q", "P ⇒ Q", "Q ⇒ R", "P ⇔ R", "¬P ∨ Q ∧ R ⇒ Q"], ["F", "T", "F", "T", "T", "T"], [["F", "false"], ["T", "true"], ["F", "false"], ["T", "true"], ["T", "true"], ["T", "true"]], "Last: left side (¬P) ∨ (Q ∧ R) = F, so F ⇒ Q is T.", C(319, se));
  A.mcq("b2-q320", "Easy", "P ⇒ Q is equivalent to:", "¬P ∨ Q", [["Q ⇒ P", "That is the converse."], ["P ∨ ¬Q", "That is Q ⇒ P."], ["¬P ⇒ ¬Q", "That is the inverse."]], "Also ≡ ¬Q ⇒ ¬P (contrapositive).", P(320, "logic-equivalence"));
  A.mcq("b2-q321", "Easy", "By De Morgan, ¬(P ∧ Q) ≡ ___ and ¬(P ∨ Q) ≡ ___.", "¬P ∨ ¬Q; ¬P ∧ ¬Q", [["¬P ∧ ¬Q; ¬P ∨ ¬Q", "Swapped."], ["¬P ∧ Q; P ∨ ¬Q", "Negate both."], ["P ∨ Q; P ∧ Q", "Negations dropped."]], "Flip the connective, negate each.", P(321, "logic-equivalence"));
  A.mcq("b2-q322", "Easy", "P ⇔ Q ≡", "(P ⇒ Q) ∧ (Q ⇒ P)", [["(P ⇒ Q) ∨ (Q ⇒ P)", "That is always true."], ["P ∧ Q", "Misses the both-false case."], ["¬P ∨ Q", "That is P ⇒ Q only."]], "Biconditional elimination.", P(322, "logic-equivalence"));
  A.match("b2-q323", "Medium", "Match the term.", [["literal", "an atom or its negation"], ["clause", "a disjunction of literals"], ["CNF", "a conjunction of clauses"], ["complementary literals", "P and ¬P"]], [], "Resolution vocabulary.", P(323, "logic-resolution"));
  A.multi("b2-q324", "Easy", "Which are propositions?", [["'It is raining.'", true, "true or false"], ["'Close the door.'", false, "a command"], ["'Is it cold?'", false, "a question"], ["'2 + 2 = 4.'", true, "true"]], "Declarative statements only.", P(324, sy));
  A.mcq("b2-q325", "Medium", "R = 'it rains', W = 'the road is wet', U = 'I take an umbrella'. 'If it rains, the road is wet and I take an umbrella.'", "R ⇒ (W ∧ U)", [["(R ⇒ W) ∧ U", "U is part of the conclusion."], ["R ∧ W ∧ U", "No 'if'."], ["(W ∧ U) ⇒ R", "Converse."]], "If-then → ⇒.", P(325, sy));
