  A.blanks("b2-q327", "Medium", "KB = P ∧ (P ⇒ Q). Of the four models, KB is true in ___ model(s); in it Q is ___ (true/false), so KB ___ Q (entails / does not entail).", ["models", "Q", "relation"], ["1", "true", "entails"], [["1", "one"], ["true", "T"], ["entails", "does entail", "⊨"]], "Model checking.", C(327, "logic-model-checking"));
  A.tf("b2-q328", "Medium", "KB = (P ∨ Q) ∧ ¬P entails Q.", true, "KB true only when P = F, then P ∨ Q needs Q = T.", "Disjunctive syllogism.", P(328, "logic-model-checking", { trap: false }));
