  A.mcq("b2-q331", "Medium", "α ⊨ β iff M(α) ___ M(β).", "⊆", [["⊇", "Backwards."], ["=", "Too strong."], ["∩ = ∅", "That would be contradiction."]], "Every α-model is a β-model.", P(331, "logic-model-checking"));
