  A.blanks("b2-q336", "Medium", "Resolution: clauses C1 P, C2 ¬P ∨ Q, C3 ¬Q. Resolving C1 and C2 gives ___; resolving that with C3 gives ___ (write 'empty').", ["C1 + C2", "with C3"], ["Q", "empty"], [["Q"], ["empty", "{}", "□", "empty clause"]], "Empty clause ⇒ KB ⊨ Q.", P(336, "logic-resolution"));
  A.mcq("b2-q337", "Medium", "Resolve (P ∨ Q ∨ R) with (¬Q ∨ S):", "P ∨ R ∨ S", [["P ∨ Q ∨ R ∨ S", "Q and ¬Q cancel."], ["P ∨ R", "S is kept."], ["empty clause", "Other literals remain."]], "Drop the complementary pair, keep the rest.", P(337, "logic-resolution"));
