  A.blanks("b2-q394", "Medium", "Exact methods that avoid repeated work: ___ and ___.", ["first", "second"], ["variable elimination", "clustering"], [["variable elimination", "clustering"], ["clustering", "variable elimination"]], "Reuse intermediate results.", P(394, en));
