  A.mcq("b2-q402", "Easy", "Bird network: can Tweety fly, and via which path?", "Yes: Tweety → Canary → Bird (can Fly)", [["No: Canary has no fly link", "Inherit from Bird."], ["Yes: Tweety → Penguin → Bird", "Tweety is a Canary."], ["Unknown", "Inheritance answers it."]], "Walk upward.", P(402, rs));
