  A.mcq("b2-q417", "Medium", "The key difference between a semantic network and an ontology:", "an ontology formally defines what concepts and relations mean, enabling reliable reasoning", [["ontologies cannot have hierarchies", "They do."], ["semantic networks are formal", "They are informal."], ["none", "There is a key difference."]], "Formal semantics.", P(417, on));
